-- Outlines that decide which records count as being in a place. Ingestion and coverage stay
-- rectangle-based (a run's bbox is what was read); an outline only filters what the map and the
-- agent tools count. The Live bbox reaches into Nevada, Oregon, Arizona and Mexico.
create table boundaries (
	slug text primary key,
	name text not null,
	-- Where the outline came from and when, since boundaries get revised.
	source_url text not null,
	retrieved_on date not null,
	outline extensions.geometry(MultiPolygon, 4326) not null
);

-- See the datasets migration: closes the table to the public Data API roles.
alter table boundaries enable row level security;

-- California from the US Census Bureau's TIGER state boundary (public domain, January 1, 2026
-- vintage), retrieved from TIGERweb's States layer (below) as GeoJSON. It includes state waters to
-- 3 nautical miles offshore, so beaches, tide pools and the islands count. Simplified with
-- ST_SimplifyPreserveTopology at 0.001 degrees (~100 m, well under a ~375 m FIRMS pixel), from
-- 12,102 vertices to 1,485, and written to 5 decimals.
insert into boundaries (slug, name, source_url, retrieved_on, outline)
